<template><section class="admin-workspace"><div class="catalog-heading"><div><p class="eyebrow">内容治理</p><h1>评价管理</h1></div><button class="icon-button" title="刷新评价" aria-label="刷新评价" @click="load">↻</button></div><form class="admin-filter" @submit.prevent="search"><select v-model="deleted"><option value="false">有效评价</option><option value="true">已删除评价（审计）</option></select><button class="secondary-button">筛选</button></form><PageStatus :loading="loading" :error="error" :empty="!result?.items.length" empty-text="没有评价记录" @retry="load"/><div class="review-admin-list"><article v-for="review in result?.items" :key="review.id" class="review-item"><div><strong>{{ review.buyerNickname }}</strong><span class="rating-stars">{{ '★'.repeat(review.rating) }}</span><time>{{ date(review.createdAt) }}</time></div><p>{{ review.content || '未填写文字评价' }}</p><small>商品 #{{ review.productId }} · {{ review.specification }}</small><p v-if="review.deleted" class="muted">删除原因：{{ review.deletionReason }} · {{ date(review.deletedAt ?? '') }}</p><button v-else class="text-action danger-text" @click="target=review">删除违规评价</button></article></div><PagePagination v-if="result" :total="result.total" :page="result.page" :busy="loading" @change="changePage"/><form v-if="target" class="inline-form" @submit.prevent="remove"><h3>删除评价</h3><p>{{ target.buyerNickname }}：{{ target.content || '未填写文字评价' }}</p><label class="form-field">删除原因<textarea v-model="reason" maxlength="500" required rows="3" placeholder="说明违规、辱骂或无关内容"></textarea></label><div class="order-actions"><button class="primary-button danger-button" :disabled="busy || !reason.trim()">确认删除</button><button type="button" class="secondary-button" @click="target=null">取消</button></div><p v-if="actionError" class="form-message-error">{{ actionError }}</p></form></section></template>
<script setup lang="ts">
import { ref } from 'vue'; import PageStatus from '../components/PageStatus.vue'; import PagePagination from '../components/PagePagination.vue'; import { errorMessage } from '../api/catalog'; import { deleteAdminReview, listAdminReviews, type AdminReview, type Page } from '../api/orders'
const result=ref<Page<AdminReview>|null>(null),target=ref<AdminReview|null>(null),loading=ref(false),busy=ref(false),error=ref(''),actionError=ref(''),deleted=ref('false'),reason=ref(''),page=ref(1)
function date(s:string){return s?s.replace('T',' ').slice(0,16):'—'}
async function load(){loading.value=true;error.value='';try{result.value=await listAdminReviews({page:page.value,size:20,deleted:deleted.value==='true'})}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function search(){page.value=1;void load()}function changePage(p:number){page.value=p;void load()}
async function remove(){if(!target.value)return;busy.value=true;actionError.value='';try{await deleteAdminReview(target.value.id,reason.value.trim());target.value=null;reason.value='';await load()}catch(e){actionError.value=errorMessage(e)}finally{busy.value=false}}
void load()
</script>
